9	    assert.equal(isValidLocode("sgsin"), true);
10	  });
11	
12	  test("malformed codes are invalid", () => {
13	    assert.equal(isValidLocode("NL"), false);
14	    assert.throws(() => countryOf("12345"), RangeError);
15	  });
16	
17	  test("country", () => {
18	    assert.equal(countryOf("DEHAM"), "DE");
