  test("vessel classes", () => {
    assert.equal(vesselClass("panamax")?.teu, 5000);
    const hamburg = portByCode("DEHAM");
    assert.ok(hamburg);
    assert.equal(classesForPort(hamburg).some((v) => v.name === "ULCV"), false);
  });

  test("Neopanamax class", () => {
    assert.deepEqual(vesselClass("Neopanamax"), {
      name: "Neopanamax",
      lengthM: 366,
      beamM: 51,
      draftM: 15,
      teu: 14000,
    });
    const singapore = portByCode("SGSIN");
    const gdynia = portByCode("PLGDY");
    assert.ok(singapore);
    assert.ok(gdynia);
    assert.equal(classesForPort(singapore).some((v) => v.name === "Neopanamax"), true);
    assert.equal(classesForPort(gdynia).some((v) => v.name === "Neopanamax"), false);
  });
});

